                                    log::debug!("remote connection: {e}");
                                }
                                if paired.load(Ordering::SeqCst) {
                                    shared.pools.paired.fetch_sub(1, Ordering::SeqCst);
                                } else {
                                    shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
                                }
                            });
                    }
                })?
        };
        Ok(Self {
            addr,
            requests,
            frames,
            stop,
            thread: Some(thread),
